<?php
declare(strict_types=1);
require_once __DIR__.'/../bootstrap.php'; Auth::requireRole('admin');
$active='notifications'; $pageTitle='Notifications'; $pageDescription='Review queued and delivered email notifications.';
$pdo=db(); $status=(string)($_GET['status']??''); $allowed=['queued','sent','failed'];
$sql="SELECT n.id,n.subject,n.message,n.status,n.attempts,n.created_at,n.sent_at,u.name,u.email FROM notifications n JOIN users u ON u.id=n.user_id WHERE n.channel='email'"; $args=[];
if(in_array($status,$allowed,true)){ $sql.=' AND n.status=?'; $args[]=$status; } $sql.=' ORDER BY n.id DESC LIMIT 200';
$stmt=$pdo->prepare($sql);$stmt->execute($args);$rows=$stmt->fetchAll(PDO::FETCH_ASSOC);
function notificationBadge(string $s):string{return match($s){'sent'=>'success','failed'=>'danger',default=>'warning'};}
?><!doctype html><html lang="en"><head><link rel="icon" href="<?= e(url('/assets/images/favicon-32.png')) ?>"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Notifications · DogoFlow Admin</title><?php require __DIR__ . '/../partials/tailwind.php'; ?></head><body class="admin-shell"><?php require __DIR__.'/../partials/admin_sidebar.php';?><section class="admin-main"><?php require __DIR__.'/../partials/admin_topbar.php';?><main class="admin-content"><div class="page-heading"><div><h1>Notifications</h1><p>Review email delivery queue and recent delivery status.</p></div><a class="btn-df primary" href="<?= e(url('/admin/publish-notification.php')) ?>" style="align-self:center">Publish notification</a></div><article class="panel-df"><form method="get" style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:18px"><select class="checkout-input" name="status" style="max-width:220px"><option value="">All statuses</option><?php foreach(['queued','sent','failed'] as $s):?><option value="<?=e($s)?>" <?=$status===$s?'selected':''?>><?=e(ucfirst($s))?></option><?php endforeach;?></select><button class="btn btn-primary">Filter</button><a class="btn btn-outline" href="<?=e(url('/admin/notifications.php'))?>">Reset</a></form><div class="table-wrap-df"><table class="table-df"><thead><tr><th>Recipient</th><th>Message</th><th>Status</th><th>Attempts</th><th>Created</th><th>Sent</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e((string)$r['name'])?></strong><div style="font-size:.75rem;color:#64748B"><?=e((string)$r['email'])?></div></td><td><strong><?=e((string)($r['subject']??'DogoFlow update'))?></strong><div style="font-size:.78rem;color:#64748B;max-width:420px;white-space:normal"><?=e(mb_strimwidth((string)$r['message'],0,180,'…'))?></div></td><td><span class="badge-df <?=e(notificationBadge((string)$r['status']))?>"><?=e(ucfirst((string)$r['status']))?></span></td><td><?= (int)$r['attempts']?></td><td><?=e(date('d M Y H:i',strtotime((string)$r['created_at'])))?></td><td><?=$r['sent_at']?e(date('d M Y H:i',strtotime((string)$r['sent_at']))):'—'?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6"><div class="empty-df">No email notifications found.</div></td></tr><?php endif;?></tbody></table></div><p style="margin-top:16px;color:#64748B;font-size:.8rem">Email delivery is processed by the private CLI worker. Configure the sender address and schedule the worker through your hosting control panel.</p></article></main></section></body></html>
